import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] secondLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(secondLine[i]) % m;
        }

        Set<Integer> set1 = new HashSet<>();
        Set<Integer> set2 = new HashSet<>();

        buildSubsets(set1, a, 0, n / 2, 0, m);
        buildSubsets(set2, a, n / 2, n, 0, m);

        List<Integer> list2 = new ArrayList<>(set2);
        Collections.sort(list2);

        int maxSum = 0;
        for (int val : set1) {
            int target = m - val;
            int idx = Collections.binarySearch(list2, target);
            if (idx < 0) {
                idx = -idx - 1;
            }
            if (idx > 0) {
                int candidateSum = val + list2.get(idx - 1);
                if (candidateSum > maxSum) {
                    maxSum = candidateSum;
                }
            }
        }
        System.out.println(maxSum);
    }

    private static void buildSubsets(Set<Integer> subsetSet, int[] a, int start, int end, int total, int m) {
        if (start == end) {
            subsetSet.add(total % m);
        } else {
            buildSubsets(subsetSet, a, start + 1, end, (total + a[start]) % m, m);
            buildSubsets(subsetSet, a, start + 1, end, total, m);
        }
    }
}
